function getDashboardData() {
	const companies = buildCompanies_();
	const clusters = buildClusters_(companies);
	const activeCompanies = companies.filter(company => company.status === "Aktif").length;
	const totalCompanies = companies.length;
	const setupCompanies = totalCompanies - activeCompanies;
	const featuredCompany = companies.find(company => company.status === "Aktif") || companies[0];
	const accessProfiles = buildAccessProfiles_(companies);

	return {
		title: APP_TITLE,
		buildVersion: APP_BUILD,
		generatedAt: formatDate_(new Date()),
		currentDateLabel: formatDateLabel_(new Date()),
		currentTimeLabel: formatTimeLabel_(new Date()),
		subtitle: "Tampilan depan per cluster. Klik nama perusahaan untuk membuka dashboard detail.",
		metrics: [
			{ label: "Total Cluster", value: clusters.length, detail: "Semua cluster perusahaan" },
			{ label: "Total Perusahaan", value: totalCompanies, detail: "Data awal dari master perusahaan" },
			{ label: "Perusahaan Aktif", value: activeCompanies, detail: `${setupCompanies} masih setup` },
			{ label: "Live Site", value: companies.reduce((sum, company) => sum + company.metrics.liveSites, 0), detail: "Akumulasi tampilan detail" },
			{ label: "User Aktif", value: companies.reduce((sum, company) => sum + company.metrics.activeUsers, 0), detail: "Akun operasional terdaftar" }
		],
		clusters,
		companies,
		accessProfiles,
		defaultAccessId: accessProfiles[0] ? accessProfiles[0].id : "",
		featuredCompanyId: featuredCompany ? featuredCompany.id : "",
		notices: [
			{ title: "Landing cluster sudah siap", detail: "Klik nama perusahaan untuk berpindah ke panel detail di sisi kanan." },
			{ title: "Data saat ini masih template", detail: "Nanti angka KPI bisa dihubungkan ke spreadsheet atau database sumber." },
			{ title: "Project terpisah dari Menejemen Pakan", detail: "Semua HTML dan route dashboard hanya ada di folder Main Dashboard." }
		],
		tips: [
			"Gunakan halaman ini untuk presentasi struktur cluster dan perusahaan.",
			"Kalau layout sudah cocok, langkah berikutnya tinggal sambungkan KPI per perusahaan.",
			"Project ini aman dipisah dari bot input pakan."
		],
		modules: getModulesFromSheet_()
	};
}

function buildAccessProfiles_(companies) {
	const profiles = [
		{
			id: "super-admin",
			name: "Admin MAXMAR",
			role: "Super Admin",
			scope: "all",
			companyId: "",
			avatarInitials: "AM",
			notificationCount: 8
		}
	];

	companies.forEach(company => {
		profiles.push({
			id: `company-${company.id.toLowerCase()}`,
			name: company.name,
			role: "Admin Perusahaan",
			scope: "company",
			companyId: company.id,
			avatarInitials: company.code.slice(0, 2),
			notificationCount: company.status === "Aktif" ? 3 : 1
		});
	});

	return profiles;
}

function buildCompanies_() {
  const sheetData = getClustersAndCompaniesFromSheet_();
  const companies = [];
  
  if (sheetData) {
    // Gunakan data dari spreadsheet
    sheetData.companies.forEach((company, globalIndex) => {
      let isActive = false;
      let status = "Setup";
      
      if (company.status === "Aktif") {
        isActive = true;
        status = "Aktif";
      } else if (company.status === "Legacy") {
        isActive = globalIndex % 3 === 0;
        status = isActive ? "Aktif" : "Setup";
      }
      
      let clusterId = company.cluster;
      let clusterName = company.cluster;
      // In new schema, company.cluster is cluster_id, we need cluster_name for region
      if (company.status !== "Legacy") {
         const clusterObj = sheetData.clusters.find(c => c.id === company.cluster);
         if (clusterObj) clusterName = clusterObj.name;
      }
      
      const code = company.code || company.name.split(" ").map(w => w[0]).join("").toUpperCase().substring(0, 4);
      
      companies.push({
        id: company.id,
        cluster: clusterId,
        name: company.name,
        code: code,
        region: clusterName,
        status: status,
        coveragePercent: isActive ? 92 : 26,
        summary: isActive ? "Data operasional siap dipantau" : "Menunggu integrasi data",
        latestPeriodLabel: isActive ? "Jul 2026" : "Setup data",
        metrics: buildCompanyMetrics_(globalIndex, isActive),
        quickMenu: buildQuickMenu_(),
        statusRows: buildStatusRows_(globalIndex, isActive),
        activities: buildActivities_(company.name, isActive),
        monthlyCards: buildMonthlyCards_(globalIndex, isActive),
        chart: buildChart_(globalIndex, isActive)
      });
    });
  } else {
    // Fallback ke config lokal jika koneksi gagal
    DASHBOARD_CLUSTER_CONFIGS.forEach((clusterItem, clusterIndex) => {
      clusterItem.companies.forEach((company, companyIndex) => {
        const globalIndex = companies.length;
        companies.push({
          id: `COMP${String(globalIndex + 1).padStart(2, "0")}`,
          cluster: clusterItem.cluster,
          name: company.name,
          code: company.code,
          region: company.region,
          status: company.status,
          coveragePercent: company.status === "Aktif" ? 92 : 26,
          summary: company.status === "Aktif" ? "Data operasional siap dipantau" : "Menunggu integrasi data",
          latestPeriodLabel: company.status === "Aktif" ? "Jul 2026" : "Setup data",
          metrics: buildCompanyMetrics_(globalIndex, company.status === "Aktif"),
          quickMenu: buildQuickMenu_(),
          statusRows: buildStatusRows_(globalIndex, company.status === "Aktif"),
          activities: buildActivities_(company.name, company.status === "Aktif"),
          monthlyCards: buildMonthlyCards_(globalIndex, company.status === "Aktif"),
          chart: buildChart_(globalIndex, company.status === "Aktif")
        });
      });
    });
  }
  
  return companies;
}

function buildClusters_(companies) {
  const sheetData = getClustersAndCompaniesFromSheet_();
  
  if (sheetData) {
    return sheetData.clusters.map((clusterItem, index) => {
      const cleanClusterName = clusterItem.name.replace(/^cluster\s+/i, "").trim();
      const clusterCompanies = companies.filter(company => company.cluster === clusterItem.id || company.cluster.toLowerCase() === cleanClusterName.toLowerCase());
      const activeCompanies = clusterCompanies.filter(company => company.status === "Aktif").length;
      
      return {
        id: clusterItem.id,
        name: clusterItem.name,
        companyIds: clusterCompanies.map(company => company.id),
        companyCount: clusterCompanies.length,
        connectedCompanies: activeCompanies,
        totalSites: clusterCompanies.reduce((sum, company) => sum + company.metrics.liveSites, 0),
        status: activeCompanies > 0 ? "Aktif" : "Setup"
      };
    });
  } else {
    // Fallback
    return DASHBOARD_CLUSTER_CONFIGS.map((clusterItem, index) => {
      const clusterCompanies = companies.filter(company => company.cluster === clusterItem.cluster);
      const activeCompanies = clusterCompanies.filter(company => company.status === "Aktif").length;
      
      return {
        id: `CL${String(index + 1).padStart(2, "0")}`,
        name: `Cluster ${clusterItem.cluster}`,
        companyIds: clusterCompanies.map(company => company.id),
        companyCount: clusterCompanies.length,
        connectedCompanies: activeCompanies,
        totalSites: clusterCompanies.reduce((sum, company) => sum + company.metrics.liveSites, 0),
        status: activeCompanies > 0 ? "Aktif" : "Setup"
      };
    });
  }
}

function buildCompanyMetrics_(index, isActive) {
	return {
		liveSites: isActive ? 12 + (index % 5) * 3 : 8 + (index % 4) * 2,
		activeUsers: isActive ? 36 + (index % 4) * 11 : 18 + (index % 3) * 5,
		permissions: isActive ? 14 + (index % 3) * 3 : 6 + (index % 2) * 2,
		finance: `Rp ${(52 + index * 2.4).toFixed(1)} M`,
		solar: `${980 + index * 55} L`,
		limbah: `${18 + index * 2} kg`,
		hm: `${7 + (index % 5)} trip`,
		lastUpdated: formatDate_(new Date()),
		highlight: isActive ? "Operasional berjalan" : "Masih tahap setup"
	};
}

