function formatDate_(date) {
	return Utilities.formatDate(date, Session.getScriptTimeZone(), "dd MMM yyyy HH:mm");
}

function formatDateLabel_(date) {
	return Utilities.formatDate(date, Session.getScriptTimeZone(), "EEEE, dd MMM yyyy");
}

function formatTimeLabel_(date) {
	return Utilities.formatDate(date, Session.getScriptTimeZone(), "HH:mm 'WIB'");
}

function getModulesFromSheet_() {
  try {
    const ss = SpreadsheetApp.openById("1bM98ecqLd8mV0mez1TGftOwv9-l4fNTHmt527z9v03s");
    const sheetModules = ss.getSheetByName("MODULES");
    const sheetSub = ss.getSheetByName("SUBMODULES");
    
    if (!sheetModules) return getLegacyModulesFromSheet_(ss);
    
    // Get Modules
    const lastRowMod = sheetModules.getLastRow();
    if (lastRowMod < 2) return []; 
    // Headers: module_id (0), module_name (2), icon (4)
    const modValues = sheetModules.getRange(2, 1, lastRowMod - 1, 5).getValues();
    
    // Get Submodules
    let subValues = [];
    if (sheetSub) {
      const lastRowSub = sheetSub.getLastRow();
      if (lastRowSub > 1) {
        // Headers: module_id, category, menu_name, url
        subValues = sheetSub.getRange(2, 1, lastRowSub - 1, 4).getValues();
      }
    }
    
    const modules = [];
    for (let i = 0; i < modValues.length; i++) {
      const modId = String(modValues[i][0]).trim();
      const modName = String(modValues[i][2]).trim();
      const modIcon = String(modValues[i][4]).trim() || "widgets";
      
      if (!modName) continue;
      
      // Find submodules for this module
      const mySubs = subValues.filter(row => String(row[0]).trim() === modId);
      
      if (mySubs.length > 0) {
        // Group by category
        const cats = {};
        mySubs.forEach(row => {
          const cat = String(row[1]).trim() || "Uncategorized";
          const menuName = String(row[2]).trim();
          const url = String(row[3]).trim();
          if (!cats[cat]) cats[cat] = [];
          cats[cat].push({ name: menuName, url: url });
        });
        
        const categories = Object.keys(cats).map(catName => ({
          name: catName,
          items: cats[catName]
        }));
        
        modules.push({
          id: modId,
          name: modName,
          icon: modIcon,
          categories: categories
        });
      } else {
        modules.push({
          id: modId,
          name: modName,
          icon: modIcon,
          categories: []
        });
      }
    }
    return modules;
  } catch (e) {
    Logger.log("Error in getModulesFromSheet_: " + e.toString());
    return [
      { name: "Budidaya", categories: [] },
      { name: "Gudang", categories: [] }
    ];
  }
}

function getLegacyModulesFromSheet_(ss) {
    const sheet = ss.getSheetByName("Data Base");
    if (!sheet) return [];
    
    const lastRow = sheet.getLastRow();
    if (lastRow < 2) return []; 
    
    const values = sheet.getRange(2, 2, lastRow - 1, 1).getValues();
    const modules = [];
    for (let i = 0; i < values.length; i++) {
      const val = String(values[i][0]).trim();
      if (val) {
        modules.push(val);
      }
    }
    return modules;
}

function getClustersAndCompaniesFromSheet_() {
  try {
    const ss = SpreadsheetApp.openById("1bM98ecqLd8mV0mez1TGftOwv9-l4fNTHmt527z9v03s");
    const sheetClusters = ss.getSheetByName("CLUSTERS");
    const sheetCompanies = ss.getSheetByName("COMPANIES");
    
    if (!sheetClusters || !sheetCompanies) {
       return getLegacyClustersAndCompaniesFromSheet_(ss);
    }
    
    let clusters = [];
    const lastRowC = sheetClusters.getLastRow();
    if (lastRowC > 1) {
       // Headers: ["cluster_id", "cluster_code", "cluster_name", "region", "folder_id", "status", "sort_order", "created_at", "updated_at"]
       const cValues = sheetClusters.getRange(2, 1, lastRowC - 1, 3).getValues();
       clusters = cValues.map(row => ({ id: row[0], name: row[2] })).filter(c => c.name);
    }
    
    let companies = [];
    const lastRowComp = sheetCompanies.getLastRow();
    if (lastRowComp > 1) {
       // Headers: ["company_id", "cluster_id", "company_code", "company_name", "company_short_name", "location_name", "folder_id", "logo_url", "theme", "status", "setup_status", "sort_order", "created_at", "updated_at"]
       const compValues = sheetCompanies.getRange(2, 1, lastRowComp - 1, 10).getValues();
       companies = compValues.map(row => ({
          id: row[0],
          cluster: row[1],
          code: row[2],
          name: row[3],
          status: row[9] === "ACTIVE" || row[9] === "Aktif" ? "Aktif" : "Setup"
       })).filter(c => c.name);
    }
    
    if (clusters.length === 0 && companies.length === 0) {
        return getLegacyClustersAndCompaniesFromSheet_(ss);
    }
    
    return { clusters, companies };
  } catch (e) {
    Logger.log("Error in getClustersAndCompaniesFromSheet_: " + e.toString());
    return null;
  }
}

function getLegacyClustersAndCompaniesFromSheet_(ss) {
    const sheet = ss.getSheetByName("Data Base");
    if (!sheet) return null;
    
    const lastRow = sheet.getLastRow();
    if (lastRow < 1) return null;
    
    const values = sheet.getRange(1, 1, lastRow, 1).getValues();
    const clusters = [];
    const companies = [];
    
    let currentClusterName = "";
    
    for (let i = 0; i < values.length; i++) {
      const val = String(values[i][0]).trim();
      if (!val) continue;
      
      const isClusterHeader = /^(cl|clu)ster/i.test(val);
      if (isClusterHeader) {
        currentClusterName = val;
        clusters.push({
          name: val,
          id: val.toLowerCase().replace(/\s+/g, "-")
        });
      } else if (currentClusterName) {
        const cleanCluster = currentClusterName.replace(/^(cl|clu)ster\s+/i, "").trim();
        const compId = val.toLowerCase().replace(/[^a-z0-9]/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "");
        companies.push({
          id: compId || ("comp-" + Math.random().toString(36).substr(2, 5)),
          name: val,
          cluster: cleanCluster,
          status: "Legacy"
        });
      }
    }
    
    if (clusters.length === 0) return null;
    return { clusters, companies };
}

function getAwalTextChunksCount() {
  const size = 200000;
  return Math.ceil(AWAL_TEXT_DATA_URI.length / size);
}

function getAwalTextChunk(index) {
  const size = 200000;
  const start = index * size;
  return AWAL_TEXT_DATA_URI.substring(start, start + size);
}

